from pathlib import Path
import sys,json
from collections import defaultdict
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from mlcourse.bike_starter import load_development,mae,write_csv
HERE=Path(__file__).resolve().parent
config=json.loads((HERE/'my_config.json').read_text())
def validate_inputs(fields,hour):
    if fields != ['hr']:raise ValueError('Only hr is approved for this previous-day task; target components and future measured weather are unavailable.')
    if type(hour) is not int or not 0<=hour<=23:raise ValueError('hr must be an integer in 0..23')
validate_inputs(config['whitelist'],0)
train,validation,audit=load_development(ROOT)
labels=defaultdict(list)
for r in train:labels[r['hr']].append(r['cnt'])
means={hour:sum(values)/len(values) for hour,values in sorted(labels.items())}
rows=[]
for r in validation:
    validate_inputs(config['whitelist'],r['hr'])
    pred=means[r['hr']];actual_high=r['cnt']>=config['fixed_actual_high']
    row={'instant':r['instant'],'datetime':r['datetime'],'hr':r['hr'],'prediction':pred,'cnt':r['cnt'],'absolute_error':abs(pred-r['cnt']),'actual_high':actual_high}
    for threshold in config['alert_thresholds']:
        alert=pred>=threshold
        row['alert_'+str(threshold)]=alert
        row['outcome_'+str(threshold)]=('hit' if actual_high else 'false_alert') if alert else ('miss' if actual_high else 'correct_no_alert')
    rows.append(row)
counts=[]
for threshold in config['alert_thresholds']:
    values={key:sum(r['outcome_'+str(threshold)]==key for r in rows) for key in ['hit','false_alert','miss','correct_no_alert']}
    assert sum(values.values())==len(rows)
    values.update(threshold=threshold,n=len(rows),alerts=values['hit']+values['false_alert'],actual_high=values['hit']+values['miss'],precision=(values['hit']/(values['hit']+values['false_alert'])) if values['hit']+values['false_alert'] else None,recall=values['hit']/(values['hit']+values['miss']))
    counts.append(values)
failures=[]
for fields,hour in [(config['failure_attempt'],8),(['hr'],24),(['temp'],8)]:
    try:validate_inputs(fields,hour)
    except ValueError as e:failures.append({'fields':fields,'hour':hour,'rejected':True,'reason':str(e)})
    else:raise AssertionError('Invalid input was accepted')
out=HERE/'artifacts'/'personal';out.mkdir(parents=True,exist_ok=True)
write_csv(out/'predictions.csv',rows)
write_csv(out/'traces.csv',[r for r in rows if r['datetime'] in config['trace_datetimes']])
write_csv(out/'counts.csv',counts)
write_csv(out/'hour_parameters.csv',[{'hour':hour,'training_n':len(labels[hour]),'training_mean':means[hour]} for hour in means])
summary={'config':config,'data_sha256':audit['data_sha256'],'training_rows':len(train),'validation_rows':len(rows),'mae':mae([r['cnt'] for r in rows],[r['prediction'] for r in rows]),'counts':counts,'failure_checks':failures,'sealed_test_evaluated':False,'causal_claim_supported':False}
(out/'summary.json').write_text(json.dumps(summary,ensure_ascii=False,sort_keys=True,indent=2)+'\n')
print(json.dumps({'mae':summary['mae'],'counts':counts,'failure_checks':failures},ensure_ascii=False))
